import{_ as a,o as i,c as t,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const b=JSON.parse('{"title":"ZViewerCLI 本地代理","description":"","frontmatter":{},"headers":[],"relativePath":"basic/cli.md","filePath":"basic/cli.md","lastUpdated":1790784636000}'),l={name:"basic/cli.md"};function o(d,e,c,h,n,s){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="zviewercli-本地代理" tabindex="-1">ZViewerCLI 本地代理 <a class="header-anchor" href="#zviewercli-本地代理" aria-label="Permalink to &quot;ZViewerCLI 本地代理&quot;">​</a></h1><p><a href="https://github.com/Zero-wyc/ZViewerCLI" target="_blank" rel="noreferrer">ZViewerCLI</a> 是可选的本地代理客户端（Go 编写），用于解决浏览器无法使用本地 Bilibili Cookie 获取高画质地址的问题。</p><h2 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to &quot;功能&quot;">​</a></h2><ul><li>使用本地 Bilibili Cookie 解析视频，获取大会员等高画质地址。</li><li>本地代理视频流，注入 Referer / Origin / User-Agent，处理 CDN 防盗链与 CORS。</li><li>一起听模块的歌词页背景视频高画质。</li></ul><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><p>从 <a href="https://github.com/Zero-wyc/ZViewerCLI/releases" target="_blank" rel="noreferrer">ZViewerCLI Releases</a> 下载对应平台二进制（如 <code>zviewer-cli-windows-amd64.exe</code>），放到任意目录运行。</p><h2 id="配置-v0-2-0" tabindex="-1">配置（v0.2.0+） <a class="header-anchor" href="#配置-v0-2-0" aria-label="Permalink to &quot;配置（v0.2.0+）&quot;">​</a></h2><p>运行后打开终端显示的本地配置页，需填写两项：</p><table tabindex="0"><thead><tr><th>配置</th><th>说明</th></tr></thead><tbody><tr><td>服务器地址</td><td>ZViewer 后端地址，如 <code>https://zviewer.example.com</code></td></tr><tr><td>Cookie</td><td>Bilibili 登录 Cookie（网页端 F12 → Application → Cookies 复制）</td></tr></tbody></table><p>可选填用户名。保存后 CLI 注册到服务器，对所有房间可用，无需房间号。</p><p>也可从 ZViewer 网页端进入：一起听 / B站相关设置页的 CLI 配置入口会自动带上服务器地址与当前用户名。</p><h2 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to &quot;使用&quot;">​</a></h2><ol><li>双击启动CLI，并填入服务器地址</li><li>在房间设置里打开对应功能开关，即可自动使用本地代理，无需逐房间连接。</li><li>前端按登录用户名过滤代理列表，可用列表中只包含当前用户自己的 CLI。</li></ol><p>运行原理与协议细节见<a href="/advanced/cli-protocol">拓展教程 · ZViewerCLI 代理协议</a>。</p>',14)])])}const _=a(l,[["render",o]]);export{b as __pageData,_ as default};
